style.css:
@-moz-document url-prefix("chrome://dino") {
body {
    background: linear-gradient(#f6f1e7, #ede3d6) !important;
    margin: 0 !important;
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    height: 100vh !important;
  }

  canvas {
    display: none !important; /* hides the Dino game */
  }

  #main-message {
    display: none !important; /* hides default text */
  }

  body::after {
    content: "✨ No Internet ✨\nTake a deep breath and relax ?";
    white-space: pre-line;
    font-size: 28px;
    font-weight: 600;
    font-family: "Segoe UI", "Inter", sans-serif;
    color: #5a4631;
    text-align: center;
    padding: 20px;
    border-radius: 16px;
    background: rgba(255, 255, 255, 0.6);
    box-shadow: 0 6px 20px rgba(0,0,0,0.1);
    backdrop-filter: blur(4px);
  }
}
